import{_ as a,o as e,c as r,a5 as o}from"./chunks/framework.BF53ZjCA.js";const _=JSON.parse('{"title":"分级","description":"","frontmatter":{"title":"分级"},"headers":[],"relativePath":"zh/grading/intro.md","filePath":"zh/grading/intro.md","lastUpdated":1789230763000}'),d={name:"zh/grading/intro.md"};function i(n,t,s,h,l,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="分级" tabindex="-1">分级 <a class="header-anchor" href="#分级" aria-label="Permalink to &quot;分级&quot;">​</a></h1><p>分级是把宝石的外观、重量与报告特征组织成可比较描述的行业惯例； 真实性由鉴定与处理披露支持，而不是由分级单独证明。 本模块讲解 GIA 4C 钻石分级框架（Carat / Color / Clarity / Cut）， 以及彩色宝石独立的 hue-tone-saturation 模型， 并列出每类瑕疵 / 处理 / 产地披露的规范。</p><h2 id="分级主题" tabindex="-1">分级主题 <a class="header-anchor" href="#分级主题" aria-label="Permalink to &quot;分级主题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>概述</th></tr></thead><tbody><tr><td><a href="./diamond-4cs.html">GIA 4C 钻石分级</a></td><td>GIA 于 1953 年确立并广泛采用的钻石分级框架。四要素——克拉、颜色、 净度、切工——相互独立又联合决定钻石价格。</td></tr><tr><td><a href="./colored-stones.html">彩色宝石分级（hue / tone / saturation）</a></td><td>彩色宝石不像钻石有标准化 4C，而是用三维度描述颜色——hue（色相）、tone （色调明暗）、saturation（饱和度）。许多实验室会使用这组描述维度， 但具体报告术语与阈值可能不同。</td></tr><tr><td><a href="./clarity-types.html">净度瑕疵类型 (inclusion / blemish)</a></td><td>宝石内含物 (inclusion) 与表面瑕疵 (blemish) 的种类、位置、数量、 可见性共同决定净度等级。同种瑕疵在不同宝石中影响不同—— 祖母绿中的&quot;花园&quot;是常态，钻石中却致命。</td></tr><tr><td><a href="./origin-disclosure.html">产地 / 处理披露</a></td><td>行业规范 (CIBJO / FTC / AGTA) 要求销售方明示宝石是否经过处理以及是否 经过产地判定。常见处理类型依价格影响分级。</td></tr></tbody></table>',4)])])}const m=a(d,[["render",i]]);export{_ as __pageData,m as default};
